param([string]$OutputPath)
$ErrorActionPreference = 'Stop'
$root = Split-Path $PSScriptRoot -Parent
$core = @(Get-Content -LiteralPath (Join-Path $root 'assets/i18n/core.packs.txt') -Encoding UTF8 | Where-Object { $_ -and -not $_.StartsWith('#') })
$extra = @(Get-Content -LiteralPath (Join-Path $root 'assets/i18n/extended.packs.txt') -Encoding UTF8 | Where-Object { $_ -and -not $_.StartsWith('#') })
$calibration = @(Get-Content -LiteralPath (Join-Path $root 'assets/i18n/calibration.packs.txt') -Encoding UTF8 | Where-Object { $_ -and -not $_.StartsWith('#') })
$calibrationSafety = @(Get-Content -LiteralPath (Join-Path $root 'assets/i18n/calibration-safety.packs.txt') -Encoding UTF8 | Where-Object { $_ -and -not $_.StartsWith('#') })
$calibrationFlow = @(Get-Content -LiteralPath (Join-Path $root 'assets/i18n/calibration-flow.packs.txt') -Encoding UTF8 | Where-Object { $_ -and -not $_.StartsWith('#') })
$calibrationShortCable = @(Get-Content -LiteralPath (Join-Path $root 'assets/i18n/calibration-short-cable.packs.txt') -Encoding UTF8 | Where-Object { $_ -and -not $_.StartsWith('#') })
$expected = $core[0].Split('|').Count
foreach ($row in $core) { if ($row.Split('|').Count -ne $expected) { throw ('Core row count: ' + $row.Split('|')[0]) } }
foreach ($row in $extra) { if ($row.Split('|').Count -ne 7) { throw ('Extended row count: ' + $row.Split('|')[0]) } }
foreach($rows in @($calibration,$calibrationSafety,$calibrationFlow,$calibrationShortCable)) {
 $columnCount=$rows[0].Split('|').Count
 foreach($row in $rows){if($row.Split('|').Count -ne $columnCount){throw ('Calibration row count: '+$row.Split('|')[0])}}
}
function Literal([string]$value) { return '@"' + $value.Replace('"','""') + '"' }
$source = "// Generated by tools/Generate-InternationalCatalog.ps1; edit assets/i18n/*.packs.txt.`r`nnamespace Xiongxin.OWTS.Localization { internal static partial class InternationalText {`r`n"
$source += "static readonly string[] CoreRows = {`r`n" + (($core | ForEach-Object { '    ' + (Literal $_) + ',' }) -join "`r`n") + "`r`n};`r`n"
$source += "static readonly string[] ExtraRows = {`r`n" + (($extra | ForEach-Object { '    ' + (Literal $_) + ',' }) -join "`r`n") + "`r`n};`r`n"
$source += "static readonly string[] CalibrationRows = {`r`n" + (($calibration | ForEach-Object { '    ' + (Literal $_) + ',' }) -join "`r`n") + "`r`n};`r`n"
$source += "static readonly string[] CalibrationSafetyRows = {`r`n" + (($calibrationSafety | ForEach-Object { '    ' + (Literal $_) + ',' }) -join "`r`n") + "`r`n};`r`n"
$source += "static readonly string[] CalibrationFlowRows = {`r`n" + (($calibrationFlow | ForEach-Object { '    ' + (Literal $_) + ',' }) -join "`r`n") + "`r`n};`r`n"
$source += "static readonly string[] CalibrationShortCableRows = {`r`n" + (($calibrationShortCable | ForEach-Object { '    ' + (Literal $_) + ',' }) -join "`r`n") + "`r`n};`r`n} }`r`n"
if([String]::IsNullOrWhiteSpace($OutputPath)){$OutputPath=Join-Path $root 'src/InternationalText.Generated.cs'}
[IO.File]::WriteAllText([IO.Path]::GetFullPath($OutputPath), $source, [Text.UTF8Encoding]::new($true))
Write-Output ('Core keys=' + ($expected-1) + '; packs=' + $core.Count + '; extended keys=' + $extra.Count)
